    let root_map = pack_valid_root_map_dag(root_map_source.path());
    let store = tempfile::tempdir().unwrap();
    let conditional_built = build_for(
        store.path(),
        &conditional.root,
        conditional.dependencies(),
        ROOT_ID,
    );
    let root_map_built = build_for(
        store.path(),
        &root_map.root,
        root_map.dependencies(),
        ROOT_ID,
    );
    let conditional_module = text(&conditional_built, "emitted_module_cid");
    let conditional_construction = text(&conditional_built, "receipt_cid");
    let root_map_module = text(&root_map_built, "emitted_module_cid");
    let root_map_construction = text(&root_map_built, "receipt_cid");
    let (mut conditional_runtime, conditional_call, _) = execute_call(
        store.path(),
        &conditional_module,
        "composition-v2-cross",
        PRIVATE_SENTINEL,
    );
    let (mut root_map_runtime, root_map_call, _) = execute_call(
        store.path(),
        &root_map_module,
        "composition-v1-cross",
        PRIVATE_SENTINEL,
