#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CapabilityCompositionStep {
    role: String,
    capability_contract_cid: Cid,
    input_schema_cid: Cid,
    output_schema_cid: Cid,
}

