    pub fn new(
        role: impl Into<String>,
        capability_contract_cid: Cid,
        input_schema_cid: Cid,
        output_schema_cid: Cid,
    ) -> Result<Self, ExecutionCompositionError> {
        let step = Self {
            role: role.into(),
            capability_contract_cid,
            input_schema_cid,
            output_schema_cid,
        };
        step.verify_integrity()?;
        Ok(step)
    }

    pub fn role(&self) -> &str {
        &self.role
    }

    pub fn capability_contract_cid(&self) -> &Cid {
        &self.capability_contract_cid
    }

    fn verify_integrity(&self) -> Result<(), ExecutionCompositionError> {
        validate_role(&self.role)?;
        validate_cid(&self.capability_contract_cid)?;
        validate_cid(&self.input_schema_cid)?;
        validate_cid(&self.output_schema_cid)
    }
}

