use unicodex_core::ObjectStore;

use super::{npm_tarball_capsule, verification, MAX_RECEIPT_BYTES, SCHEMA_V1, SCHEMA_V2};

#[derive(Clone, Copy, Eq, PartialEq)]
pub(super) enum Profile {
    RootMapV10,
    ConditionalExportsV11,
}

pub(super) fn recognized_schema_hint(store: &ObjectStore, cid: &str) -> Option<&'static str> {
    let receipt = verification::load_value(store, cid, MAX_RECEIPT_BYTES).ok()?;
    let schema = verification::text_value(&receipt, "schema").ok()?;
    Profile::from_receipt_schema(schema)
        .ok()
        .map(Profile::receipt_schema)
}

impl Profile {
    pub(super) fn from_construction_schema(schema: &str) -> Result<Self> {
        match schema {
            npm_tarball_capsule::EXPORTS_ROOT_MAP_DAG_TREE_RECEIPT_SCHEMA => Ok(Self::RootMapV10),
            npm_tarball_capsule::CONDITIONAL_EXPORTS_DAG_TREE_RECEIPT_SCHEMA => {
                Ok(Self::ConditionalExportsV11)
            }
            _ => bail!("composition-call receipt construction profile is unsupported"),
        }
    }

    pub(super) fn from_receipt_schema(schema: &str) -> Result<Self> {
        match schema {
            SCHEMA_V1 => Ok(Self::RootMapV10),
            SCHEMA_V2 => Ok(Self::ConditionalExportsV11),
            _ => bail!("composition-call receipt schema is unsupported"),
        }
    }

    pub(super) fn receipt_schema(self) -> &'static str {
        match self {
            Self::RootMapV10 => SCHEMA_V1,
            Self::ConditionalExportsV11 => SCHEMA_V2,
        }
    }
}

